 "content": "def transform(grid):
    """Reduce each 3x3 cell block to its color other than background 0 or 5."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    if grid[r][c] not in (0, 5):
                        out[br][bc] = grid[r][c]
                        break
                if out[br][bc] != 0:
                    break
    return out
